// File-hash audit only. No curve arithmetic, solver, or timed work is run.
#include "native_helpers.hpp"
int main(int argc,char**argv){try{
 require(argc==3,"usage: verify_file_provenance FINAL_REPLAY_JSON NEW_HASH_AUDIT_JSON");files::path replay=argv[1],output=argv[2];require(!files::exists(output),"Refusing existing output");auto receipt=read_json(replay.string());std::set<files::path> producer_files,execution_files;for(const auto&row:receipt.at("rows").array)producer_files.insert(row.at("file").scalar);for(const auto&row:receipt.at("process_dispositions").array)execution_files.insert(row.at("file").scalar);
 std::map<files::path,std::string> verified;auto match=[&](const files::path&path,const std::string&expected){std::string observed=digest(path);require(observed==expected,"Recorded file hash mismatch");verified[path]=observed;};size_t scalar_env_flags=0;std::set<std::string> binary_hashes;
 for(const auto&path:execution_files){auto j=read_json(path.string());verified[path]=digest(path);require(j.at("status").scalar=="COMPLETED_VERIFIED","Nonverified process disposition");match(j.at("argv").at(0).scalar,j.at("binary_sha256").scalar);binary_hashes.insert(j.at("binary_sha256").scalar);for(const auto&entry:j.at("argv_existing_file_sha256").object)match(entry.first,entry.second.scalar);match(j.at("semantic_path").scalar,j.at("semantic_sha256").scalar);match(j.at("stdout_path").scalar,j.at("stdout_sha256").scalar);match(j.at("stderr_path").scalar,j.at("stderr_sha256").scalar);require(!truth(j.at("known_answer_environment_present")),"Known-answer environment recorded");++scalar_env_flags;}
 for(const auto&path:producer_files){verified[path]=digest(path);}std::ostringstream out;out<<"{\n  \"kind\":\"post_run_native_file_hash_provenance_audit\",\n  \"status\":\"PASS\",\n  \"scope\":\"Recorded executable, argv input/config, semantic, stdout and stderr hashes checked against actual bytes; no arithmetic or timing replay\",\n  \"independent_answer_receipt_sha256\":"<<qstr(digest(replay))<<",\n  \"producer_files_hashed\":"<<producer_files.size()<<",\n  \"execution_receipts_audited\":"<<execution_files.size()<<",\n  \"distinct_executable_sha256s\":"<<binary_hashes.size()<<",\n  \"known_answer_environment_false_checked\":"<<scalar_env_flags<<",\n  \"files\":[\n";size_t i=0;for(const auto&entry:verified){if(i++)out<<",\n";out<<"    {\"path\":"<<qstr(entry.first.string())<<",\"sha256\":"<<qstr(entry.second)<<"}";}out<<"\n  ]\n}\n";create_new(output,out.str());std::cout<<"PASS: "<<execution_files.size()<<" execution receipts, "<<producer_files.size()<<" producer files, "<<verified.size()<<" bound files\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
